void Scripted(){++groups;std::uint64_t state=0x126abef902dd6601ull;auto next=[&](){state^=state<<7;state^=state>>9;return state;};for(unsigned iteration=0;iteration<16384;++iteration){++cases;Banks b;std::array<std::int32_t,6> bankResults{};std::array<std::vector<std::int32_t>,6> classResults;std::optional<std::uint32_t> chosen;for(std::uint32_t j=0;j<6;++j){b[j].name_pointer=100+j;bankResults[j]=(next()%4==0)?0:((next()&1)?256:-256);if(!chosen&&bankResults[j]==0)chosen=j;auto count=next()%6;for(std::uint32_t k=0;k<count;++k){b[j].classes.push_back({1000+j*10+k,10000+j*100+k});classResults[j].push_back(next()%3==0?0:std::int32_t(0x10000));}}
const bool active=(next()&3)!=0;std::optional<std::uint32_t> ci;std::vector<std::pair<std::uint64_t,std::uint64_t>> expected;const auto bankEnd=chosen?*chosen+1:6u;for(std::uint32_t j=0;j<bankEnd;++j)expected.emplace_back(100+j,77);if(chosen&&active){for(std::uint32_t k=0;k<classResults[*chosen].size();++k){expected.emplace_back(10000+*chosen*100+k,88);if(classResults[*chosen][k]==0){ci=k;break;}}}
std::size_t call=0;auto cb=[&](std::uint64_t l,std::uint64_t r){Check(call<expected.size()&&expected[call]==std::pair<std::uint64_t,std::uint64_t>{l,r});++call;if(r==77)return bankResults[static_cast<std::size_t>(l-100)];const auto bank=static_cast<std::size_t>((l-10000)/100);const auto index=static_cast<std::size_t>((l-10000)%100);return classResults[bank][index];};auto out=Monstey_GadbSelectPointerClass(b,77,88,active?1u:0u,0,cb);Check(call==expected.size()&&out.bank_index==chosen&&out.class_index==ci);Check(out.bank_comparisons==bankEnd);Check(out.class_comparisons==expected.size()-bankEnd);const auto status=!chosen?Status::BankNotFound:(!active?Status::CategorySkipped:(ci?Status::ClassFound:Status::ClassNotFound));Check(out.status==status);if(ci)Check(out.class_identity==1000ull+*chosen*10+*ci);call=0;const Monstey_GadbPointerCategory category{88,active?1u:0u,0};const auto borrowed=Monstey_GadbSelectPointerClass(b,77,category,cb);Check(call==expected.size());Check(borrowed.status==out.status&&borrowed.bank_index==out.bank_index&&borrowed.class_index==out.class_index&&borrowed.class_identity==out.class_identity&&borrowed.bank_comparisons==out.bank_comparisons&&borrowed.class_comparisons==out.class_comparisons);}}
